questionvariables.text:
/* First we define a random factor of the fourth term */
kk:rand(4)+2;
/* to determine model answers for this question */
/* We first need a value of d */
d_mod_ans:rand(4)+1;
/**/

/* We then need a value of a, calculated from k and d*/
a_mod_ans:3*d_mod_ans/(kk-1);

/* We want to make sure our model answer is nice */
while (integerp(a_mod_ans)=false) do (d_mod_ans:rand(4)+1,a_mod_ans:3*d_mod_ans/(kk-1)); 

/* Use values from above to calculate the 2nd, 3rd and 4th terms */
a_mod_ans_2:a_mod_ans+d_mod_ans;
a_mod_ans_3:a_mod_ans+2*d_mod_ans;
a_mod_ans_4:a_mod_ans+3*d_mod_ans;

/*Simplified values of the terms a */
a_simp:3*d_mod_ans/(kk-1)

feedbackvariables.text:
/* Calculate the supposed student common differences */
stud_cd_1:ans2-ans1;
stud_cd_2:ans3-ans2;
stud_cd_3:ans4-ans3;

/* Check if all common differences are the same */
eq_stud_cd:if (stud_cd_1=stud_cd_2 and stud_cd_2=stud_cd_3) then 1 else 0;

/*simplifying the solution*/
sol1:kk*ans1;
stud_d:(sol1-ans1)/3;
sol2:ans1+stud_d;
sol3:ans1+2*stud_d;

work_sol_last: if kk=2 then "" else a=3*d/(kk-1);
work_sol_last2: if kk=4 then "a" else "";
